// n8n Code node (JavaScript)
const instance = 'mo';
const baseUrl = 'https://api.arcadia-tour.cloud';
const apikey = '3049E9126A2C-4015-AD91-57C3B03CC08B';

// خُد messageId من الـ item الحالي (غيّر المسار لو مختلف عندك)
const messageId =
  $json.messageId ||
  $json?.body?.data?.message?.key?.id ||
  $json?.data?.message?.key?.id;

if (!messageId) {
  throw new Error('messageId not found in input JSON');
}

const url = `${baseUrl}/chat/getBase64FromMediaMessage/${instance}`;

const body = {
  message: { key: { id: messageId } },
  convertToMp4: false,
};

const res = await this.helpers.httpRequest({
  method: 'POST',
  url,
  headers: {
    apikey,
    'Content-Type': 'application/json',
  },
  body,
  json: true,
});

return [{ json: res }];

