const item = $input.first().json;

const driveLink = item.webViewLink;
const resumeUrl = $execution.resumeUrl;

const text = `أهلاً يا مدير، تم استلام صور ومستندات جديدة من العميل.

🗂 لينك درايف للمراجعة:
${driveLink}

برجاء مراجعة الصور وتجهيز عرض السعر (PDF) ثم اضغط:

✅ موافقة:
${resumeUrl}?decision=approve

❌ رفض:
${resumeUrl}?decision=reject`;

return [{ json: { text } }];

const items = $input.all();

const sorted = items.sort((a, b) => 
  new Date(b.json.Time_stamp) - new Date(a.json.Time_stamp)
);

return [sorted[0]];

const item = $input.item.json;
let output = item.output || item.text || item.message || item.response || '';
output = typeof output === 'object' ? JSON.stringify(output) : String(output || '');

// ── Detect if CTA already exists ──
const hasQuestion     = output.includes('؟');
const hasCTA_keywords = [
  'نبدأ','يناسبك','تحب','هل','أيهم','تفضل','اختار','اخبرني','وش رأيك','تريد','أكمل','نكمل','نحجز'
].some(kw => output.includes(kw));

const alreadyHasCTA = hasQuestion || hasCTA_keywords;

// ── Detect context ──
const hasPrice   = /\d+\s*(دولار|USD|\$|يورو|EUR)/.test(output) || output.includes('التكلفة') || output.includes('السعر');
const hasHotels  = output.includes('نجم') || output.includes('★') || output.includes('فندق') || output.includes('Hotel');
const hasBudget  = /اقتصادي|رخيص|ميزانية|توفير/.test(output);
const hasChoices = /خيار\s*[١٢٣1-3]|option\s*[1-3]/.test(output) || (output.match(/\n[١-٣1-3][.)]/g)||[]).length >= 2;

// ── Select appropriate CTA ──
let cta = '';

if (!alreadyHasCTA) {
  if (hasChoices) {
    cta = '\n\nأي خيار يناسبك؟ (1 أو 2 أو 3) 😊';
  } else if (hasBudget) {
    cta = '\n\nهل يناسبك هذا الخيار؟ أو تحب أشوف لك خيارات قريبة بنفس السعر؟ 🤝';
  } else if (hasPrice && hasHotels) {
    cta = '\n\nتحب أجهز لك عرض كامل بهذا الفندق؟ 😊';
  } else if (hasPrice) {
    cta = '\n\nهل يناسبك هذا العرض؟ نبدأ في الحجز؟ 👌';
  } else if (hasHotels) {
    cta = '\n\nأي فندق يناسبك؟ أو تحب أشوف لك خيارات ثانية؟ 😊';
  } else {
    // General — always end with a question
    cta = '\n\nكيف أقدر أساعدك أكثر؟ 😊';
  }
}

return [{ json: {
  ...item,
  output: output + cta,
  cta_injected: cta.length > 0,
  cta_text: cta.trim()
}}];

const wh = $('Webhook').first().json;
const msg = (
  wh.body?.data?.message?.conversation ||
  wh.body?.data?.message?.extendedTextMessage?.text ||
  ''
).trim();

const phone = (wh.body?.data?.key?.remoteJid || '').split('@')[0];

// ── Country detection ──
const COUNTRIES = {
  'كازاخستان': { en: 'Kazakhstan', city: 'Almaty' },
  'قازاقستان': { en: 'Kazakhstan', city: 'Almaty' },
  'الماتي':    { en: 'Kazakhstan', city: 'Almaty' },
  'روسيا':     { en: 'Russia',     city: 'Moscow' },
  'موسكو':     { en: 'Russia',     city: 'Moscow' },
  'بولندا':    { en: 'Poland',     city: 'Warsaw' },
  'وارسو':     { en: 'Poland',     city: 'Warsaw' },
  'أوزبكستان': { en: 'Uzbekistan', city: 'Tashkent' },
  'سمرقند':    { en: 'Uzbekistan', city: 'Samarkand' },
  'طشقند':     { en: 'Uzbekistan', city: 'Tashkent' },
};

let country = null, city = null;
for (const [ar, info] of Object.entries(COUNTRIES)) {
  if (msg.includes(ar)) { country = info.en; city = info.city; break; }
}

// ── Duration detection ──
// "6 أيام" "٦ أيام" "6 ايام" "سبع ليالي" etc.
const AR_NUMS = { 'صفر':0,'واحد':1,'اثنين':2,'ثلاثة':3,'أربعة':4,'خمسة':5,'ستة':6,'سبعة':7,'ثمانية':8,'تسعة':9,'عشرة':10,'أحد عشر':11,'اثنا عشر':12 };
const AR_DIGIT = {'٠':0,'١':1,'٢':2,'٣':3,'٤':4,'٥':5,'٦':6,'٧':7,'٨':8,'٩':9};
function toWestern(s){ return s.replace(/[٠-٩]/g, d => AR_DIGIT[d]); }

let durationDays = null, durationNights = null;
const dayMatch = toWestern(msg).match(/(\d+)\s*(?:يوم|أيام|ايام|days?)/i);
const nightMatch = toWestern(msg).match(/(\d+)\s*(?:ليل[ةه]|ليالي|nights?)/i);
if (dayMatch)   { durationDays = parseInt(dayMatch[1]);   durationNights = durationDays - 1; }
if (nightMatch) { durationNights = parseInt(nightMatch[1]); durationDays = durationNights + 1; }

// ── Persons detection ──
let adults = null;
const personMatch = toWestern(msg).match(/(\d+)\s*(?:شخص|أشخاص|بالغ|بالغين)/i);
if (msg.includes('شخصين') || msg.includes('اثنين')) adults = 2;
else if (msg.includes('شخص واحد') || msg.includes('فرد')) adults = 1;
else if (personMatch) adults = parseInt(personMatch[1]);

// ── Date detection ──
const MONTHS = {
  'يناير':1,'جانفي':1,'فبراير':2,'فيفري':2,'مارس':3,'أبريل':4,'ابريل':4,'مايو':5,
  'يونيو':6,'يوليو':7,'أغسطس':8,'اغسطس':8,'سبتمبر':9,'أكتوبر':10,'اكتوبر':10,
  'نوفمبر':11,'ديسمبر':12
};
let checkinDate = null, checkoutDate = null;
for (const [arMon, monNum] of Object.entries(MONTHS)) {
  const dMatch = toWestern(msg).match(new RegExp('(\\d{1,2})\\s*' + arMon));
  if (dMatch) {
    const day = parseInt(dMatch[1]);
    const year = 2026;
    const ci = new Date(year, monNum-1, day);
    checkinDate = ci.toISOString().slice(0,10);
    if (durationNights) {
      const co = new Date(ci); co.setDate(co.getDate() + durationNights);
      checkoutDate = co.toISOString().slice(0,10);
    }
    break;
  }
}

// Default checkin: 30 days from now if not found but nights known
if (!checkinDate && durationNights) {
  const ci = new Date(); ci.setDate(ci.getDate() + 30);
  checkinDate = ci.toISOString().slice(0,10);
  const co = new Date(ci); co.setDate(co.getDate() + durationNights);
  checkoutDate = co.toISOString().slice(0,10);
}

// ── Is budget request? ──
const isBudget = /اقتصادي|رخيص|ميزانية|بأقل|أرخص|توفير/.test(msg);

// ── Intent classification ──
// Package request = has country + (nights OR date) + persons
const hasCountry   = !!country;
const hasDuration  = durationNights !== null;
const hasPersons   = adults !== null;
const hasDate      = !!checkinDate;

const isPackageRequest = hasCountry && (hasDuration || hasDate) && hasPersons;
const isGeneralInquiry = !isPackageRequest;

return [{
  json: {
    intent:          isPackageRequest ? 'package_request' : 'general_inquiry',
    is_package:      isPackageRequest,
    country,
    city,
    adults:          adults || 2,
    children:        0,
    total_persons:   adults || 2,
    children_ages:   [],
    duration_nights: durationNights || null,
    checkin_date:    checkinDate || null,
    checkout_date:   checkoutDate || null,
    is_budget:       isBudget,
    raw_message:     msg,
    phone,
    // Debug flags
    has_country:     hasCountry,
    has_duration:    hasDuration,
    has_persons:     hasPersons,
    has_date:        hasDate,
  }
}];

const intent = $('Intent Detector').first().json;

// After Merge node, data from both Fetch Hotels and Fetch Services is available
// $('Fetch Hotels') and $('Fetch Services') are accessible via node name references
let hotelRes = null, svcRes = null;

try { hotelRes = $('Fetch Hotels').first().json; } catch(e) { hotelRes = null; }
try { svcRes   = $('Fetch Services').first().json; } catch(e) { svcRes = null; }

// Also try reading from merged input items as backup
if (!hotelRes || !svcRes) {
  const allItems = $input.all();
  allItems.forEach(item => {
    const d = item.json;
    if (Array.isArray(d)) {
      // Array = hotels response
      if (!hotelRes) hotelRes = d;
    } else if (d && d.costs) {
      // Has costs = services response
      if (!svcRes) svcRes = d;
    } else if (d && d.success !== undefined && Array.isArray(d.packages)) {
      // Already-processed hotels
      if (!hotelRes) hotelRes = d;
    }
  });
}

// ── Normalize hotels ──
let hotels = [], hotels_error = false;
try {
  if (!hotelRes) {
    hotels_error = true;
  } else if (Array.isArray(hotelRes)) {
    hotels = hotelRes.filter(h => h && Object.keys(h).length > 0);
  } else if (Array.isArray(hotelRes.packages)) {
    hotels = hotelRes.packages;
  } else if (hotelRes.status === 'no_results' || hotelRes.status === 'fallback') {
    hotels = [];
  } else if (hotelRes.error || hotelRes.message) {
    hotels_error = true;
  } else if (typeof hotelRes === 'object') {
    hotels = [hotelRes];
  }
} catch(e) { hotels_error = true; }

// ── Normalize services ──
let services = {}, currency = 'USD', includes = {transfer:true,rent:true,sim:true};
try {
  if (svcRes && !svcRes.error) {
    services = svcRes.costs || svcRes;
    currency  = svcRes.currency || 'USD';
    includes  = svcRes.includes || includes;
  }
} catch(e) {}

const needs_fallback = hotels_error || hotels.length === 0;

return [{ json: {
  hotels, services, currency, includes, intent,
  hotels_count: hotels.length,
  services_ok:  !!(svcRes && svcRes.costs),
  needs_fallback, hotels_error,
  _debug: {
    hotelRes_type: Array.isArray(hotelRes) ? 'array:'+hotels.length : typeof hotelRes,
    svcRes_ok: !!(svcRes && svcRes.costs)
  }
}}];

const intent   = $('Intent Detector').first().json;
const phone    = intent.phone;

// Safe get calculate result
let calcRes;
try { calcRes = $('Calculate Price').first().json; } catch(e) { calcRes = null; }

const DEST_AR = {
  'Kazakhstan': 'كازاخستان 🇰🇿',
  'Russia':     'روسيا 🇷🇺',
  'Poland':     'بولندا 🇵🇱',
  'Uzbekistan': 'أوزبكستان 🇺🇿',
};

const destAr = DEST_AR[intent.country] || intent.country;
const nights = intent.duration_nights;
const adults = intent.adults;

// If calculate failed or returned error
const calcFailed = !calcRes || calcRes.error || calcRes.message || calcRes.success === false;
if (calcFailed) {
  return [{ json: {
    output: `تم استلام طلبك ✅\n\n📍 الوجهة: ${destAr}\n📅 المدة: ${nights ? nights+' ليلة' : 'غير محدد'}\n👥 الأشخاص: ${adults}\n\nسأتواصل معك قريباً بالعرض الكامل والأسعار الدقيقة 🤝\n\nأو تقدر تتواصل معنا مباشرة: wa.me/77051181845`,
    phone
  }}];
}

// Normal formatting
const currency = calcRes?.currency || 'USD';
const budgetLbl = currency === 'EUR' ? 'EUR €' : 'USD $';
let options = calcRes?.options || calcRes?.packages || [];

if (!Array.isArray(options) || options.length === 0) {
  return [{ json: {
    output: `أكيد 😊 نقدر نجهز عرض ${destAr} لمدة ${nights} ليلة/${adults} أشخاص\n\nفي خيارات متعددة من فنادق اقتصادية للفاخرة ✨\n\nهل تحب أجهز لك عرض مفصل؟ أو تحدد لي ميزانيتك التقريبية؟ 😊`,
    phone
  }}];
}

const top3 = options.slice(0, 3);
let msg = `✨ عرض ${destAr} — ${nights} ليلة / ${adults} ${adults===1?'شخص':'أشخاص'}\n${'─'.repeat(28)}\n\n`;
const nums = ['1️⃣','2️⃣','3️⃣'];
top3.forEach((opt, i) => {
  const stars = '⭐'.repeat(Number(opt.stars || opt.Star_Rating || 0));
  const name  = opt.hotel_name || opt.Hotel_Name || `خيار ${i+1}`;
  const price = Number(opt.total_customer_price || opt.total_price || 0);
  const room  = opt.room_type || opt.Room_Type_Name || '';
  const lbl   = i===0?' 💚 الأوفر':i===top3.length-1?' ✨ الفاخر':' ⚖️ متوازن';
  msg += `${nums[i]} *${name}* ${stars}${lbl}\n`;
  if(room) msg += `   🛏️ ${room}\n`;
  msg += `   💰 ${price.toLocaleString()} ${budgetLbl} (شامل الخدمات)\n\n`;
});
if(intent.checkin_date) msg += `📅 الوصول: ${intent.checkin_date} → ${intent.checkout_date}\n`;
msg += `\n✅ شامل: نقل المطار + إيجار سيارة + شريحة اتصال\n\n`;
msg += intent.is_budget
  ? `أي خيار يناسبك؟ أو أشوف لك خيارات بنفس الميزانية؟ 🤝`
  : `أي خيار يناسبك؟ (1 أو 2 أو 3) 👌`;

return [{ json: { output: msg, phone } }];

// Preserve original Webhook data AND add Status
const webhookJson = $('Webhook').first().json;
const item = $input.item?.json || {};

const hasStatus = typeof item.Status === 'string' && item.Status.length > 0;
const status = hasStatus ? item.Status : 'Active';

// Pass through EVERYTHING from Webhook + add Status
return [{
  json: {
    ...webhookJson,          // body.data.messageType etc
    _botStatus: status,      // renamed to avoid conflict
    _statusSource: hasStatus ? 'sheet' : 'default'
  }
}];
